package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.metagenomics.*;

/** Source-profile native taxonomic reassignment; external original RMA reader only. */
public final class MaltReassignCli {
 private MaltReassignCli(){ }
 private static final String ACTION="Required action: read WARNINGS.md, retain complete RMA inputs and failed attempts, and resolve the named prerequisite, input or capacity problem before retrying a NEW directory. Supply the exact permitted MALT0.4.1 MALT.jar/data.jar provider; if installation is unavailable or forbidden, skip its dependent RMA analysis. This is native serial/unpaired/naive/readCount reassignment, not alignment, experimental parallel processing, a full MALT/eager adapter or biological authentication. Original RMA files and released executables are not rewritten.";
 public static void main(String[] args){int status=run(args,System.out,System.err);if(status!=0)System.exit(status);}
 static int run(String[] args,PrintStream stdout,PrintStream stderr) {
  Path out=null;boolean owned=false;
  try {
   if(args.length==1 && args[0].equals("--help")){stdout.println("--rma CLASSIFIED_RMA6 --runtime ORIGINAL_MALT_JAR_DIRECTORY --out NEW_DIRECTORY\nNative serial/unpaired/naive/readCount profile. Defaults: --minimum-score 50 --top-percent 1 --maximum-expected 1 --minimum-identity 0 --coverage 80 --minimum-support 0 --minimum-support-percent 0.01. A positive integer minimum overrides percentage; zero keeps the original base minimum1 and percentage selection.\nOptional --disabled-taxonomy-ids FILE (literal integer per line). Complete-input positive capacities: --maximum-input-bytes 1000000000 --maximum-reads 1000000 --maximum-matches 10000000 --maximum-matches-per-read 100000 --maximum-text-characters 10000000 --maximum-classifications 1000000 --maximum-taxonomy-characters 100000000 --maximum-taxonomy-nodes 3000000 --maximum-taxonomy-depth 1024.\n"+ACTION);return 0;}
   var allowed=Set.of("--rma","--runtime","--out","--minimum-score","--top-percent","--maximum-expected","--minimum-identity","--coverage","--minimum-support","--minimum-support-percent","--disabled-taxonomy-ids","--maximum-input-bytes","--maximum-reads","--maximum-matches","--maximum-matches-per-read","--maximum-text-characters","--maximum-classifications","--maximum-taxonomy-characters","--maximum-taxonomy-nodes","--maximum-taxonomy-depth");var options=new LinkedHashMap<String,String>();
   for(int i=0;i<args.length;i+=2)if(i+1>=args.length || !allowed.contains(args[i]) || options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require unique complete options; see --help");
   if(!options.keySet().containsAll(Set.of("--rma","--runtime","--out")))throw new IOException("Declare input RMA, runtime and NEW output paths; see --help");
   out=Path.of(options.get("--out")).toAbsolutePath().normalize();Files.createDirectory(out);owned=true;Path rma=Path.of(options.get("--rma")).toAbsolutePath().normalize().toRealPath(),runtime=Path.of(options.get("--runtime")).toAbsolutePath().normalize();
   var readLimits=new MaltRmaReader.Limits(positive(options,"--maximum-input-bytes",1000000000),integerCapacity(options,"--maximum-reads",1000000),positive(options,"--maximum-matches",10000000),integerCapacity(options,"--maximum-matches-per-read",100000),integerCapacity(options,"--maximum-text-characters",10000000),integerCapacity(options,"--maximum-classifications",1000000));
   var treeLimits=new MaltTaxonomy.Limits(positive(options,"--maximum-taxonomy-characters",100000000),integerCapacity(options,"--maximum-taxonomy-nodes",3000000),integerCapacity(options,"--maximum-taxonomy-depth",1024));
   int configured=options.containsKey("--minimum-support")?Integer.parseInt(options.get("--minimum-support")):0;if(configured<0)throw new IOException("Minimum support must be nonnegative");
   float percent=real(options,"--minimum-support-percent",0.01f,0,Float.MAX_VALUE);boolean overridden=configured>0;if(overridden)percent=0;
   Set<Integer> disabled=new LinkedHashSet<>();Path ids=null;NextflowFiles.Pin disabledPin=null;if(options.containsKey("--disabled-taxonomy-ids")) {
    ids=Path.of(options.get("--disabled-taxonomy-ids")).toAbsolutePath().normalize().toRealPath();disabledPin=NextflowFiles.pin(ids,readLimits.inputBytes(),()->{});
    for(String line:Files.readAllLines(ids))if(disabled.size()>=treeLimits.nodes() || !disabled.add(Integer.valueOf(line)))throw new IOException("Duplicate/over-capacity literal disabled taxon IDs");
   }
   var parameters=new MaltReassignment.Options(real(options,"--minimum-score",50,0,Float.MAX_VALUE),real(options,"--top-percent",1,0,100),real(options,"--maximum-expected",1,0,Float.MAX_VALUE),real(options,"--minimum-identity",0,0,100),real(options,"--coverage",80,0,100),configured==0?1:configured,percent,disabled);
   var result=MaltReassignment.reassign(runtime,rma,parameters,readLimits,treeLimits);var warnings=new ArrayList<String>(result.warnings());if(overridden)warnings.add("MINIMUM_SUPPORT_OVERRIDE: positive --minimum-support disabled percentage selection, matching original MALT option resolution.");
   try(var writer=Files.newBufferedWriter(out.resolve("assignments.tsv"),StandardOpenOption.CREATE_NEW)) {
    writer.write("uid\tread_name_base64\tsource_weight\tstored_taxon\tinitial_taxon\tfinal_taxon\ttotal_matches\tavailable_matches\tactive_indices\n");
    for(var row:result.rows())writer.write(row.uid()+"\t"+(row.name()==null?"NULL":Base64.getEncoder().encodeToString(row.name().getBytes(StandardCharsets.UTF_8)))+"\t"+row.sourceWeight()+"\t"+row.storedTaxon()+"\t"+row.initialTaxon()+"\t"+row.finalTaxon()+"\t"+row.totalMatches()+"\t"+row.availableMatches()+"\t"+row.activeIndices()+"\n");
   }
   var document=new LinkedHashMap<String,Object>();document.put("status","native-malt041-serial-unpaired-naive-readCount-reassignment-only");document.put("selected_minimum_support",result.selectedMinimum());document.put("parameters",Map.of("minimum_score",parameters.minimumScore(),"top_percent",parameters.topPercent(),"maximum_expected",parameters.maximumExpected(),"minimum_identity",parameters.minimumIdentity(),"coverage",parameters.coverage(),"configured_minimum_support",parameters.minimumSupport(),"support_percent",parameters.supportPercent(),"disabled_taxa",disabled));document.put("reads",result.source().reads());document.put("stored_matches",result.source().storedMatches());document.put("available_matches",result.source().availableMatches());document.put("input",signature(result.source().input()));document.put("upstream_program",signature(result.source().program()));document.put("upstream_data",signature(result.source().data()));document.put("getter_profile",Map.of("minimum_score",result.source().profile().minimumScore(),"maximum_expected",result.source().profile().maximumExpected(),"read_sequence",result.source().profile().sequence()));document.put("direct_weights",result.directWeights());document.put("relocations",result.relocations());document.put("warnings",warnings);document.put("biological_result_admitted",false);document.put("full_malt_or_eager_adapter_admitted",false);document.put("new_tool_credit",0);
   document.put("direct_weights",result.directWeights().entrySet().stream().map(entry->Map.of("taxon_id",entry.getKey(),"weight",entry.getValue())).toList());document.put("relocations",result.relocations().entrySet().stream().map(entry->Map.of("from_taxon",entry.getKey(),"to_taxon",entry.getValue())).toList());
   var after=NextflowFiles.pin(rma,readLimits.inputBytes(),()->{});if(after.bytes()!=result.source().input().bytes() || !after.sha256().equals(result.source().input().sha256()))throw new IOException("Original RMA changed during reassignment");
   if(ids!=null){if(!NextflowFiles.pin(ids,readLimits.inputBytes(),()->{}).equals(disabledPin))throw new IOException("Disabled-ID source changed during reassignment");document.put("disabled_id_input",disabledPin);}
   NextflowFiles.writeJson(out.resolve("reassignment.json"),document);Files.writeString(out.resolve("WARNINGS.md"),"# MALT reassignment component only\n\n"+String.join("\n\n",warnings)+"\n\n"+ACTION+"\n",StandardOpenOption.CREATE_NEW);NextflowFiles.writeJson(out.resolve("COMPONENT_COMPLETED.json"),Map.of("status","native-malt041-serial-reassignment-only","assignments",NextflowFiles.pin(out.resolve("assignments.tsv"),1000000000,()->{}),"report",NextflowFiles.pin(out.resolve("reassignment.json"),1000000000,()->{}),"new_tool_credit",0,"biological_result_admitted",false));stdout.println("Native MALT serial reassignment completed; "+result.source().reads()+" stored reads. Read WARNINGS.md.\n"+ACTION);return 0;
  }catch(Exception error) {
   int status=error instanceof MaltRmaReader.MissingRuntimeException?3:2;stderr.println("MALT REASSIGN "+(status==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED":"FAIL2 NO RESULT ADMITTED")+": "+error+"\n"+ACTION);
   if(owned && out!=null)try{NextflowFiles.writeJson(out.resolve("FAILURE.json"),Map.of("status",status==3?"SKIP3":"FAIL2","error",error.toString(),"required_action",ACTION));Files.writeString(out.resolve("WARNINGS_FAILURE.md"),"# "+(status==3?"SKIP3":"FAIL2")+" NO RESULT\n\n"+error+"\n\n"+ACTION+"\n",StandardOpenOption.CREATE_NEW);}catch(IOException diagnostic){stderr.println("Diagnostic write failed; retain the failed output directory: "+diagnostic);}return status;
  }
 }
 private static Map<String,Object> signature(MaltRmaReader.Signature value){return Map.of("bytes",value.bytes(),"sha256",value.sha256());}
 private static long positive(Map<String,String> values,String key,long fallback)throws IOException {long value=values.containsKey(key)?Long.parseLong(values.get(key)):fallback;if(value<1)throw new IOException("Positive complete capacity required: "+key);return value;}
 private static int integerCapacity(Map<String,String> values,String key,int fallback)throws IOException {long value=positive(values,key,fallback);if(value>Integer.MAX_VALUE)throw new IOException("Representable complete capacity required: "+key);return (int)value;}
 private static float real(Map<String,String> values,String key,float fallback,float minimum,float maximum)throws IOException {float value=values.containsKey(key)?Float.parseFloat(values.get(key)):fallback;if(!Float.isFinite(value) || value<minimum || value>maximum)throw new IOException("Finite source float in supported range required: "+key);return value;}
}
